package dev.pocketengine.features.groups;

import android.app.Application;
import dev.pocketengine.core.RunControl;
import dev.pocketengine.core.RunJournal;
import dev.pocketengine.store.TaskStore;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicBoolean;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.RuntimeEnvironment;
import org.robolectric.annotation.Config;
import static org.junit.Assert.*;

/** Actual SQLite tasks/runs/operations; native authority fixtures are explicit and revocable. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
public final class GroupTaskStoreTest {
    static final class Fixture {
        final TaskStore store=new TaskStore(RuntimeEnvironment.getApplication());final AtomicBoolean live=new AtomicBoolean(true);final GroupHostPort.Authority authority=new GroupHostPort.Authority(){public void check(){if(!live.get())throw new SecurityException("fixture native grant revoked");}public void checkRead(){if(!live.get())throw new SecurityException("fixture native read revoked");}};
        final GroupHostPort.Authority ownerRead=new GroupHostPort.Authority(){public void check(){throw new SecurityException("read only native owner");}public void checkRead(){}};
        final JSONObject source;final GroupHostPort.Request request;RunControl control;JSONObject attempt;RunJournal journal;
        Fixture(String capability,long budget)throws Exception {source=row(capability,budget);request=new GroupHostPort.Request(source);store.registerGroupTask(request,authority);}
        void start()throws Exception {control=new RunControl();control.bindTask(request.taskId);control.setAuthorityCheck(()->{authority.check();store.checkGroupTaskControl(request,control);});attempt=store.startGroupAttempt(request,authority,8);control.bindHostRun(request.taskId,attempt.getString("runId"),attempt.getInt("coordinatorEpoch"));journal=store.groupJournal(request,attempt.getString("runId"),attempt.getInt("coordinatorEpoch"),control,authority);}
    }
    static JSONObject row(String capability,long budget)throws Exception {
        String group=UUID.randomUUID().toString(),space="group:"+group;long now=System.currentTimeMillis();
        JSONObject event=new JSONObject().put("eventId",UUID.randomUUID().toString()).put("provider","qq").put("accountId","native-bot").put("roomId","native-room").put("senderId","member-a").put("messageId",UUID.randomUUID().toString()).put("transportEpoch",UUID.randomUUID().toString()).put("text","Answer only this public question").put("receivedAt",now).put("replyUntil",now+300_000).put("artifacts",new JSONArray());
        return new JSONObject().put("requestId",UUID.randomUUID().toString()).put("taskId",UUID.randomUUID().toString()).put("groupId",group).put("spaceId",space).put("actorId",UUID.randomUUID().toString()).put("goal",event.getString("text"))
                .put("capability",capability).put("resource",capability.startsWith("public.")?"public":capability.equals("group.files")?space:"media:owner-approved-service").put("audience","group").put("visibility","requester").put("policyEpoch",UUID.randomUUID().toString()).put("maxTokens",budget).put("maxMediaBytes",20*1024*1024L).put("mediaItems",capability.startsWith("media.")?1:0).put("event",event);
    }
    @Test public void immutableNativeActorSpaceNeverBecomePrivateOwner()throws Exception {Fixture f=new Fixture("public.answer",4000);JSONObject task=f.store.groupTask(f.request,f.authority);assertEquals(f.request.actorId,task.getString("actorId"));assertEquals(f.request.spaceId,task.getString("spaceId"));assertNotEquals("owner",task.getString("actorId"));assertNotEquals("private",task.getString("spaceId"));assertThrows(SecurityException.class,()->f.store.startAttempt(f.request.taskId,"capabilities",8));f.start();assertThrows(SecurityException.class,()->f.store.authorizeTools(f.request.taskId,f.attempt.getString("runId"),new JSONArray().put("memory_search")));assertThrows(SecurityException.class,()->f.store.checkCapabilityCurrent(f.request.taskId,f.attempt.getString("runId"),1,"memory_search"));}
    @Test public void exactRequestIsIdempotentButChangedGoalOrOriginCannotCollide()throws Exception {Fixture f=new Fixture("public.answer",4000);assertFalse(f.store.registerGroupTask(f.request,f.authority).getBoolean("created"));assertEquals(1,f.store.list().length());JSONObject changed=new JSONObject(f.source.toString()).put("goal","changed goal");assertThrows(SecurityException.class,()->f.store.registerGroupTask(new GroupHostPort.Request(changed),f.authority));JSONObject other=new JSONObject(f.source.toString()).put("taskId",UUID.randomUUID().toString());assertThrows(SecurityException.class,()->f.store.registerGroupTask(new GroupHostPort.Request(other),f.authority));}
    @Test public void groupJsonShapeWithoutLiveNativeAuthorityDoesNotAdmit()throws Exception {TaskStore tasks=new TaskStore(RuntimeEnvironment.getApplication());GroupHostPort.Request request=new GroupHostPort.Request(row("public.answer",4000));assertThrows(SecurityException.class,()->tasks.registerGroupTask(request,()->{throw new SecurityException("no native authority");}));assertEquals(0,tasks.list().length());}
    @Test public void cumulativeTokenReservationPersistsAcrossAttemptsWithoutRefund()throws Exception {Fixture f=new Fixture("public.answer",1000);f.start();f.store.reserveGroupModelTokens(f.request,f.attempt.getString("runId"),1,700,f.authority);f.store.endAttempt(f.request.taskId,f.attempt.getString("runId"),"paused","paused",new JSONObject());f.start();assertEquals(2,f.attempt.getInt("coordinatorEpoch"));assertThrows(IllegalStateException.class,()->f.store.reserveGroupModelTokens(f.request,f.attempt.getString("runId"),2,301,f.authority));f.store.reserveGroupModelTokens(f.request,f.attempt.getString("runId"),2,300,f.authority);assertEquals(1000,f.store.get(f.request.taskId,false).getLong("groupReservedTokens"));}
    @Test public void operationJournalAllowsOnlyThisGroupsFixedTool()throws Exception {Fixture f=new Fixture("media.image",8000);f.start();assertThrows(SecurityException.class,()->f.journal.beginOperation("phone_tap",new JSONObject()));assertThrows(SecurityException.class,()->f.journal.beginOperation("group_media_audio",new JSONObject()));String op=f.journal.beginOperation("group_media_image",new JSONObject().put("prompt","one actual image"));assertTrue(f.store.hasUnresolved(f.request.taskId));f.journal.finishOperation(op,new JSONObject().put("ok",true).put("status","response_received"));assertFalse(f.store.hasUnresolved(f.request.taskId));assertEquals("receipt",f.store.get(f.request.taskId,false).getJSONArray("operations").getJSONObject(0).getString("state"));assertThrows(SecurityException.class,()->f.journal.beginOperation("group_media_image",new JSONObject()));}
    @Test public void revocationBlocksNewEffectsButPreservesLateExactReceipt()throws Exception {Fixture f=new Fixture("media.image",8000);f.start();String op=f.journal.beginOperation("group_media_image",new JSONObject());f.live.set(false);f.journal.finishOperation(op,new JSONObject().put("ok",true).put("status","response_received"));assertFalse(f.store.hasUnresolved(f.request.taskId));assertThrows(InterruptedException.class,()->f.journal.beginOperation("group_media_image",new JSONObject()));assertNotNull(f.store.groupTask(f.request,f.ownerRead));assertThrows(SecurityException.class,()->f.ownerRead.check());}
    @Test public void unknownOperationAfterRestartIsOnlyQueryableNeverGeneratedAgain()throws Exception {Fixture f=new Fixture("media.image",8000);f.start();String op=f.journal.beginOperation("group_media_image",new JSONObject());f.journal.finishOperation(op,new JSONObject().put("code","media_unknown").put("accepted",JSONObject.NULL));TaskStore reopened=new TaskStore(RuntimeEnvironment.getApplication());assertEquals("reconciling",reopened.groupTask(f.request,f.ownerRead).getString("status"));assertThrows(SecurityException.class,()->reopened.startGroupAttempt(f.request,f.authority,8));reopened.resolveOperation(f.request.taskId,op,"not_occurred");assertThrows(SecurityException.class,()->reopened.startGroupAttempt(f.request,f.authority,8));}
    @Test public void staleCancelCannotStopANewerExactRunAndRevisionMonotonic()throws Exception {Fixture f=new Fixture("public.answer",8000);f.start();String old=f.attempt.getString("runId");long initial=f.store.get(f.request.taskId,false).getLong("groupStateRevision");f.store.endAttempt(f.request.taskId,old,"paused","pause",new JSONObject());f.start();assertThrows(SecurityException.class,()->f.store.cancelGroupTask(f.request,old,1,f.control,f.authority));assertFalse(f.control.isCancelled());JSONObject cancelled=f.store.cancelGroupTask(f.request,f.attempt.getString("runId"),2,f.control,f.authority);assertTrue(cancelled.getLong("groupStateRevision")>initial);assertTrue(f.control.isCancelled());}
    @Test public void lateCompletionCannotOverwriteGroupCancellationOrResumeTerminal()throws Exception {Fixture f=new Fixture("public.answer",8000);f.start();String run=f.attempt.getString("runId");f.store.cancelGroupTask(f.request,run,1,f.control,f.authority);f.store.event(f.request.taskId,run,1,new JSONObject().put("type","result").put("status","completed"));f.store.endAttempt(f.request.taskId,run,"completed","late success",new JSONObject());assertEquals("cancelled",f.store.get(f.request.taskId,false).getString("status"));assertThrows(SecurityException.class,()->f.store.startGroupAttempt(f.request,f.authority,8));}
    @Test public void sameOperationReceiptIsIdempotentButConflictingReceiptIsRejected()throws Exception {Fixture f=new Fixture("media.image",8000);f.start();String op=f.journal.beginOperation("group_media_image",new JSONObject());JSONObject real=new JSONObject().put("ok",true).put("status","response_received");f.journal.finishOperation(op,real);f.journal.finishOperation(op,real);assertThrows(SecurityException.class,()->f.journal.finishOperation(op,new JSONObject().put("ok",false)));}
}
